/***********************************************************
 * 1. Base Structure & Layout Wrappers
 ***********************************************************/
.bfusion-root {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
}
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-chart-wrap {
  width: 100%;
  height: 100%;
  overflow: hidden;
  position: relative;
  /* anchor for absolute-positioned tooltip */
}
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
/***********************************************************
 * 2. Landing Page
 ***********************************************************/
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
}
.bfusion-landing__metadata a {
  color: #8C8C8C;
  text-decoration: none;
}
.bfusion-landing__metadata a:hover {
  text-decoration: underline;
}
/***********************************************************
 * 3. Legend Bar (horizontal, above chart)
 ***********************************************************/
.bfusion-legend-bar {
  background: #fff;
  flex-wrap: wrap;
  user-select: none;
}
/***********************************************************
 * 3b. Toolbar: timeline slicer + unit slicer
 *     Same shape and the same segmented control as
 *     bfusion-ResourceHeatmap's .rh-controls / .rh-seg.
 ***********************************************************/
.bfusion-controls {
  display: flex;
  align-items: center;
  gap: 8px 18px;
  padding: 0 14px;
  box-sizing: border-box;
  background: #fff;
  border-bottom: 1px solid #eee;
  user-select: none;
  overflow: hidden;
}
.bfusion-controls__group {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}
.bfusion-controls__group--unit {
  margin-left: auto;
}
.bfusion-controls__label {
  font-size: 9.5px;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #aaa;
  white-space: nowrap;
}
.bfusion-seg {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  background: #f2f3f5;
  border: 1px solid #e0e0e0;
  border-radius: 999px;
}
.bfusion-seg__btn {
  appearance: none;
  border: none;
  background: transparent;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 550;
  color: #888;
  padding: 3px 11px;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  line-height: 1.5;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}
.bfusion-seg__btn:hover:not(:disabled) {
  color: #333;
  background: rgba(255, 255, 255, 0.75);
}
.bfusion-seg__btn--active {
  background: #fff;
  color: #333;
  font-weight: 650;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
.bfusion-seg__btn:disabled {
  color: #c4c8ce;
  cursor: not-allowed;
  background: transparent;
}
.bfusion-seg__btn:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/***********************************************************
 * 4. Enhanced Data Table
 ***********************************************************/
.bfusion-table-wrap {
  /* Slim custom scrollbars */
}
.bfusion-table-wrap::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.bfusion-table-wrap::-webkit-scrollbar-thumb {
  background: #c8c8c8;
  border-radius: 3px;
}
.bfusion-table-wrap::-webkit-scrollbar-thumb:hover {
  background: #aaa;
}
.bfusion-table-wrap::-webkit-scrollbar-track {
  background: #f5f5f5;
}
.bfusion-data-table {
  border-spacing: 0;
  /* Row hover effect */
  /* Sticky left columns shadow when scrolled */
}
.bfusion-data-table tbody tr:hover td {
  background-color: #f0f4ff !important;
}
.bfusion-data-table td[style*="sticky"],
.bfusion-data-table th[style*="sticky"] {
  box-shadow: 2px 0 4px rgba(0, 0, 0, 0.04);
}
/***********************************************************
 * 5. Insights: vertical toggle strip + sidebar
 ***********************************************************/
/* Always-visible vertical on/off bar. Clicking it expands or collapses the
   panel, which starts collapsed — the same affordance as the Resource
   Heatmap's .rh-insight-strip. */
.bfusion-insight-strip {
  background: #f4f5f7;
  border-left: 1px solid #e5e7eb;
  color: #888;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.bfusion-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
  line-height: 1;
}
.bfusion-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-size: 9px;
  font-weight: 650;
  color: #aaa;
  text-transform: uppercase;
}
.bfusion-insight-strip:hover,
.bfusion-insight-strip:focus {
  background: #eceef1;
  color: #333;
  outline: none;
}
.bfusion-insight-strip:hover .bfusion-insight-strip__label,
.bfusion-insight-strip:focus .bfusion-insight-strip__label {
  color: #888;
}
.bfusion-insight-strip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.bfusion-sidebar {
  /* Slim scrollbar */
}
.bfusion-sidebar::-webkit-scrollbar {
  width: 5px;
}
.bfusion-sidebar::-webkit-scrollbar-thumb {
  background: #d0d0d0;
  border-radius: 3px;
}
.bfusion-sidebar::-webkit-scrollbar-track {
  background: transparent;
}
/* Scope chip — says what the panel is describing, and clears it. */
.bfusion-scope-chip {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  padding: 2px 8px;
  border: 1px solid rgba(217, 123, 41, 0.35);
  border-radius: 999px;
  background: rgba(217, 123, 41, 0.08);
  color: #9a5418;
  font-family: inherit;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bfusion-scope-chip__x {
  color: #b1712f;
  font-weight: 700;
}
.bfusion-scope-chip:hover {
  background: rgba(217, 123, 41, 0.16);
}
/* Every period named in the panel is a cross-filter button. */
.bfusion-period-btn {
  appearance: none;
  border: 1px solid #e0e2e6;
  background: #fff;
  color: #444;
  font-family: inherit;
  font-weight: 600;
  padding: 1px 7px;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.12s ease, border-color 0.12s ease, color 0.12s ease;
}
.bfusion-period-btn:hover {
  background: rgba(217, 123, 41, 0.1);
  border-color: rgba(217, 123, 41, 0.45);
  color: #9a5418;
}
.bfusion-period-btn--active {
  background: #D97B29;
  border-color: #D97B29;
  color: #fff;
}
.bfusion-period-btn:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* Full-size trend for the series whose table row is selected. */
.bfusion-trendchart-wrap {
  margin-bottom: 2px;
}
.bfusion-trendchart {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.bfusion-trendchart__axis {
  display: flex;
  justify-content: space-between;
  margin-top: 2px;
  font-size: 9px;
  color: #aaa;
}
.bfusion-trendchart__facts {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  margin-top: 7px;
  padding-top: 7px;
  margin-bottom: 10px;
  border-top: 1px solid #eceef1;
  font-size: 10px;
  color: #888;
}
.bfusion-trendchart__facts strong {
  color: #333;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}
/* Single-period read-out, shown when the focus is one column. */
.bfusion-period-detail {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  padding: 6px 9px;
  margin-bottom: 10px;
}
.bfusion-period-detail__row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 2px 0;
  font-size: 10.5px;
}
.bfusion-period-detail__row strong {
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}
.bfusion-period-detail__row + .bfusion-period-detail__row {
  border-top: 1px solid #f3f4f6;
}
/***********************************************************
 * 6. Tooltip
 ***********************************************************/
.bfusion-tooltip {
  line-height: 1.5;
  color: #333;
}
.bfusion-tooltip div {
  margin-bottom: 1px;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: #9AA0A6;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(154, 160, 166, 0.04) 120px, rgba(154, 160, 166, 0.04) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.22;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #9AA0A6;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #9AA0A6;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
